<div class="admin-two-col admin-section-gap">
<section class="card"><h2>Test order</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="supplier_id" value="<?= $id ?>"><input type="hidden" name="action" value="test_order"><div class="form-grid"><div class="field"><label>Order reference</label><input name="order_ref" maxlength="100"></div><div class="field"><label>Status</label><select name="test_status"><option>Planned</option><option>Ordered</option><option>In transit</option><option>Received</option><option>Under review</option><option>Completed</option><option>Cancelled</option></select></div><div class="field"><label>Ordered date</label><input type="date" name="ordered_at" value="<?= e(date('Y-m-d')) ?>"></div><div class="field"><label>Received date</label><input type="date" name="received_at"></div><div class="field"><label>Amount</label><input type="number" step="0.01" min="0" name="amount"></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="<?= e(strtoupper($supplier['region'] ?? '') === 'USA' ? 'USD' : 'ZAR') ?>"></div><div class="field"><label>Courier</label><input name="courier" maxlength="100"></div><div class="field"><label>Tracking reference</label><input name="tracking_ref" maxlength="160"></div><div class="field"><label>Packaging condition (1–5)</label><input type="number" min="1" max="5" name="packaging_condition"></div><div class="field admin-checks"><label><input type="checkbox" name="documentation_complete"> Documentation complete</label><label><input type="checkbox" name="batch_matches_coa"> Batch matches COA</label></div><div class="field full"><label>Notes</label><textarea name="test_notes" maxlength="5000"></textarea></div><div class="field full"><button class="btn primary">Add test order</button></div></div></form></section>
<section class="card"><h2>Test-order history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Status</th><th>Ordered</th><th>Amount</th><th>Evidence</th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td><?= e($t['order_ref'] ?: '#'.$t['id']) ?></td><td><?= e($t['status']) ?></td><td><?= e($t['ordered_at']) ?></td><td><?= sourcing_money($t['amount'],$t['currency']) ?></td><td><?= $t['documentation_complete']?'Docs ✓ ':'Docs — ' ?><?= $t['batch_matches_coa']?'Batch ✓':'Batch —' ?></td></tr><?php endforeach;?><?php if(!$tests):?><tr><td colspan="5">No test orders recorded.</td></tr><?php endif;?></tbody></table></div></section>
</div>
